import './collection.less'
import './index.less'
import HelpToChoose from '@plugins/help-to-choose-section'
import Accordion from './accordion-menu.js'

import Collection from './collection.js'


class SPCollection extends Collection {
    constructor({ swiperContainer, swiperPagination, ...props}) {
        super({...props})
        this.swiperContainer = swiperContainer
        this.swiperPagination = swiperPagination

        this.init()
    }
    isMobile () {
        const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
        return clientWidth < 1024
    }
    init() {
        const _autoplay = true
        const _speed =  8

        const _this = this

        new Swiper(this.swiperContainer, {
            slidesPerView: 'auto',
            clickable: true,
            spaceBetween: 0,
            on: {
                activeIndexChange: function () {
                    const videoIndex = ".video-" + (this.realIndex + 1)
                    const dom = document.querySelectorAll(videoIndex)

                    let currentShowDOM = null
                    dom.forEach(it => {
                        if (_this.isMobile()) {
                            it.classList.contains('block') && (currentShowDOM = it)
                        } else {
                            it.classList.contains('lg:block') && (currentShowDOM = it)
                        }
                    })
                    _this.pauseAllMedia()
                    currentShowDOM?.play()
                },
                init: function () {
                    const videoIndex = ".video-" + (this.realIndex + 1)
                    const dom = document.querySelectorAll(videoIndex)

                    let currentShowDOM = null
                    dom.forEach(it => {
                        if (_this.isMobile()) {
                            it.classList.contains('block') && (currentShowDOM = it)
                        } else {
                            it.classList.contains('lg:block') && (currentShowDOM = it)
                        }
                    })
                    _this.loadVideo(currentShowDOM, this)
                },
                resize: function () {
                    setTimeout(() => {
                        this.update()
                    }, 500);
                }
            },
            pagination: {
                el: this.swiperPagination,
                clickable: true,
                bulletClass: 'swiper-collection-work-pagination-item',
                bulletActiveClass: 'active swiper-collection-work-pagination-item-active',
                clickableClass: 'swiper-collection-work-pagination-clickable',
                modifierClass: 'swiper-collection-work-pagination-',
                renderBullet: function (index, className) {
                    const workDOM = document.querySelector('[data-work]')
                    const workArray = workDOM.dataset.work.split(',')
                    const text = workArray[index]
                    return `
                        <div class="${className}">
                            <span>${index + 1}</span>
                            <span>${text}</span>
                        </div>
                    `
                },
            },
            autoplay: _autoplay ? {
                delay: _speed * 1000,
                disableOnInteraction: false,
            } : false,
        });
    }
    loadVideo(dom, swiper) {
        dom?.addEventListener('loadedmetadata', () => {
            this.initPlay(dom)
        });

        document.querySelectorAll('.slide-video').forEach(element => {
            element.addEventListener('ended', () => {
                if(swiper.realIndex === 2) {
                    swiper.slideTo(0);
                    return
                }
                swiper.slideNext()
            })
        });
    }
    initPlay(dom) {
        this.pauseAllMedia()
        dom.play()
    }
    pauseAllMedia() {
        const swiperDOM = document.querySelector(this.swiperContainer)
        swiperDOM?.querySelectorAll('video').forEach(video => {
            video.currentTime = 0
            video.pause()
        });
    }
}

document.addEventListener("DOMContentLoaded", () => {

    new Accordion($('.accordion-menu'), false);
    const faq_btn = $(".section-collection-faq .z-button-fill-middle")
    const { moreText, lessText, } = faq_btn.data()
    faq_btn.click(function() {
        const isActive = faq_btn.hasClass("active")
        const span = faq_btn.find('span').eq(0)
        if(isActive) {
            $(".section-collection-faq .accordion-menu").removeClass("active")
            faq_btn.removeClass("active")
            span.text(moreText)
        } else {
            $(".section-collection-faq .accordion-menu").addClass("active")
            faq_btn.addClass("active")
            span.text(lessText)
        }
    })

    new SPCollection({
        swiperContainer: '.swiper-collection-work',
        swiperPagination: '.swiper-collection-work-pagination',
    });

    // 智能选购插件，接收 pageType 参数
    // PPS详情页=pps_detail，SP详情页=sp_detail，SP聚合页=sp_gather
    new HelpToChoose({ pageType: 'sp_gather' })
})
